[1879383078]={[1]="Anvil-forged Chestplate of Precision";[2]="Rúrek V promised gold and holdings to any of his people who brought him a drake’s head. ‘Strike accurately and you need strike but once!’ he proclaimed.";[3]=3;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411CB95C;[9]=0x41000004;};
[1879383079]={[1]="Winterstith Gloves of Fortitude";[2]="King Ilkún's search lasted for ten years, but ended in horror. While digging beneath the Anvil, the Zhélruka caused a great crack to split the glacier in twain. The cold-drakes who dwelt within Winterstith awoke and emerged from the rent, overwhelming the dwarves.";[3]=5;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411CB963;[9]=0x41000004;};
