[1879383132]={[1]="Reinforced Winterstith Camail of the Defender";[2]="Vethúg concealed herself in a high cavern behind a mighty waterfall near the Steel Keep, and waited. As Dáin raised his axe before his cheering people, she burst from her cave, the waterfall freezing and shattering into shards around her, and swept down upon the Longbeards.";[3]=6;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411CB92C;[9]=0x41000004;};
[1879383133]={[1]="Reinforced Winterstith Hauberk of Alacrity";[2]="‘Longbeards hurry to battle. We Zhélruka must exercise restraint, if we can. Victory comes more slowly than defeat; treasure one and not the other.’ - Brátek IV, the Brash";[3]=3;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411CB967;[9]=0x41000004;};
[1879383134]={[1]="Winterstith Trousers of Fortitude";[2]="King Ilkún's search lasted for ten years, but ended in horror. While digging beneath the Anvil, the Zhélruka caused a great crack to split the glacier in twain. The cold-drakes who dwelt within Winterstith awoke and emerged from the rent, overwhelming the dwarves.";[3]=15;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411AEFD4;[9]=0x41000004;};
