[1879383232]={[1]="Reinforced Winterstith Leggings of Shielding";[2]="The most prominent peaks of the Ered Mithrin number four: Wrathhorn, Undarbród, Thrumfall, and Winterstith. The Anvil at the base of this last has stood beyond memory of dwarves, and some say it will outstay them.";[3]=15;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411AEFD4;[9]=0x41000004;};
