[1879388236]={[1]="Birch-bark Page";[2]="So bolt your doors, make fast the shutters, And listen for his moans and mutters. Then light your lantern, torch, or lamp, To drive him back to dark and damp.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388237]={[1]="Birch-bark Page";[2]="For titbits tender still he yearns, With eyes that flare among the ferns: For foal and filly, kid and neat, And most of all, for children sweet.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388238]={[1]="Birch-bark Page";[2]="Keep close your sons and daughters dear Mind the moors and marshes drear For when the night grows black and cold Comes crawling Ubb the Mad and Old.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388239]={[1]="Birch-bark Page";[2]="Now hear the lay of Old Mad Ubb Drowned his brother in the washing-tub Sunk his bones in the boggy pools Stole his silver, gold and jewels";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388240]={[1]="Birch-bark Page";[2]="Old Mad Ubb, so quick and deft, Snatches, catches, leaves bereft The mothers of the babes he claims And leaves them crying out their names.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388241]={[1]="Birch-bark Page";[2]="They drove him deep into the bog Now he feasts on toad and frog Wriggling maggot, worm and grub: What a feast for Old Mad Ubb!";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388242]={[1]="Birch-bark Page";[2]="When cold wind wails and fir-tree creaks, Through the gloom of night he sneaks. O’er wooden wall and rooftops thatched, Unlocked window, gate unlatched.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388243]={[1]="Birch-bark Page";[2]="Caught a-thieving by his kin Cried cravenly to keep his skin Squawk and simper, squeal and sob, He fled a-howling from the mob";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879388244]={[1]="Birch-bark Page";[2]="Somewhere yet he lurks and lingers, Scrabbling with his scabby fingers. ‘Neath forest dark or dusky hill Old Mad Ubb, he hungers still.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
