[1879388359]={[1]="Mantle from the Old Ford";[2]="Woodmen and Beornings fought at the Battle of the Old Ford during the closing days of the War of the Ring. One disgraced Woodman fled rather than fight, and he was slain by his fellows for cowardice. This was his mantle, and the Woodmen of Hultvís have sent it on to you so it can be worn with courage, as it never was.";[3]=6;[4]=2;[5]=3;[6]=false;[7]=false;[8]=0x411DB892;[9]=0x41000003;};
[1879388360]={[1]="Cloak of Swift Travellers";[2]="The passage of the mountains has never been short, but when there is need of haste an entire household might move with speed.";[3]=45;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411DB88A;[9]=0x41000004;};
[1879388361]={[1]="Cloak of Hardy Travellers";[2]="The passage of the mountains has never been easy, but with such noble companions it can be made less dangerous.";[3]=45;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411DB88A;[9]=0x41000004;};
[1879388362]={[1]="Boots of the Apparition";[2]="'Where are you going? Wandering about in the mud and the muck of the Gladden Fields? Do not disturb the shades with your stomping, or you will have to deal with me.' - Grimbeorn the Old";[3]=23;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411DB89B;[9]=0x41000004;};
