[1879388365]={[1]="Shoulderpads from the Old Ford";[2]="Woodmen and Beornings fought at the Battle of the Old Ford during the closing days of the War of the Ring, but not all returned from it. The Woodmen of Hultvís repaired these shoulderpads as best they could, and sent them along to you.";[3]=6;[4]=2;[5]=3;[6]=false;[7]=false;[8]=0x411DB897;[9]=0x41000003;};
[1879388366]={[1]="Cloak of Wise Travellers";[2]="The passage of the mountains can be dangerous, but when the Wise travel abroad the wisest are those who choose not to threaten them.";[3]=45;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411DB88A;[9]=0x41000004;};
[1879388367]={[1]="Kozun's Gift";[2]="The Zhélruka warrior Kozun was pleased to have your help in the tunnels behind Skarháld, and sent along these fine greaves.";[3]=15;[4]=2;[5]=3;[6]=false;[7]=false;[8]=0x411DB88C;[9]=0x41000003;};
[1879388368]={[1]="Pauldrons from the Old Ford";[2]="Woodmen and Beornings fought at the Battle of the Old Ford during the closing days of the War of the Ring. These pauldrons were worn bravely by one great warrior, but following the battle he set aside his weapons and vowed never to fight again. The Woodmen of Hultvís sent these pauldrons along to you, that they might still serve to protect those who need it.";[3]=6;[4]=2;[5]=3;[6]=false;[7]=false;[8]=0x411DB88E;[9]=0x41000003;};
[1879388369]={[1]="Greaves of Durin";[2]="'I know the importance of agility, though my uncle Náin does not. I suppose that is why I still have both my ears!' - Durin";[3]=15;[4]=2;[5]=3;[6]=false;[7]=false;[8]=0x411DB88B;[9]=0x41000003;};
[1879388370]={[1]="Shoes of the Apparition";[2]="'I thought you were supposed to be smart. Those shoes will not keep the mud off your feet if you go stomping about in the Gladden Fields. Anyone could see that.' - Grimbeorn the Old";[3]=23;[4]=3;[5]=3;[6]=false;[7]=false;[8]=0x411DB88D;[9]=0x41000004;};
