[1879389003]={[1]="Old-elven Parchment";[2]="Anda i Lúna-taureva enyálië; Long is the Black Wood’s memory Lúna i óri i yárë aldaron. Dark are the hearts of old trees;";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389004]={[1]="Old-elven Parchment";[2]="Lencar i auri, núrar i lómi, The days are slow, the nights are deep Ai! i orontë avafanyar. But lo, comes the dawn without clouds";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389005]={[1]="Old-elven Parchment";[2]="I yernë yéni lennar lintiënen. The elder time passes swiftly; I enwinar alcari ve hisië sintar. The glories of old fade as mist.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389006]={[1]="Old-elven Parchment";[2]="Nén, a nén, tínala calima, Water, O water, bright-glinting, Nén, tercáno cuiviëva ceutana! Water, herald of life renewed!";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389007]={[1]="Old-elven Parchment";[2]="Allinta i luimë valima yassë Yet swifter is the blessed flood Ilyë nwalmai cólar Eárenna. That carries all woes to the Sea.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389008]={[1]="Old-elven Parchment";[2]="Nordo ar neldo, sánë ar tasar Oak and beech, pine and willow grey Amárië andvaë randan fuinessë. Have dwelt for an age in shadow";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
[1879389009]={[1]="Old-elven Parchment";[2]="Oiovistala, visto ilyaron, Ever-changing, changer of all, Poito niëron ar saurana taurëo. Cleanser of tears and wood befouled.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x4100319B;[9]=0x410002A9;};
