[1879404054]={[1]="Warg Tracks";[2]="These distinctive tracks could only have been made by a warg of average size or an unusually-large wolf. Neither bodes well for the few good-hearted folk who live in these wilds.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x410002B0;[9]=0x410002A9;};
[1879404055]={[1]="Eat in Silence";[2]="The rations were old and tasteless when the dwarves brought them to Skarháld, and they have not improved in the subsequent days. But they will serve a purpose: blunting your hunger and giving you a break from conversation.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x410002B0;[9]=0x410002A9;};
[1879404056]={[1]="Horn of Hunting";[2]="It is a Zhélruka tradition to blow horns of this style upon setting out upon a worm-hunt. During the long years of their adventures in the Ered Mithrin, drakes have come to recognize this sound, seeking out those who wind them.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x410002B0;[9]=0x410002A9;};
[1879404057]={[1]="Disturbed Tracks";[2]="These tracks in the dirt mark the passage of an Orc raiding party.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x410002B0;[9]=0x410002A9;};
[1879404058]={[1]="Zhélruka Sword";[2]="This sword was crafted in the Zhélruka style, packed for the journey by Venko. He has not wielded in battle, and has expressed no interest in doing so.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;[8]=0x410002B0;[9]=0x410002A9;};
